import java.util.Map;

import javax.servlet.http.HttpServletRequest;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class SampleController {

    @GetMapping("/sample")
    public Map<String, String> getSample(HttpServletRequest request) {

        // Corrected code
        // This code sanitizes the input parameter to prevent any malicious
        // command execution.
        String command = request.getParameter("command");
        if (command == null || command.isEmpty()) {
            command = "echo Hello World";
        }

        // Sanitize the input command
        String[] allowedCommands = {"echo", "ls", "cat"};
        if (!Arrays.asList(allowedCommands).contains(command)) {
            command = "echo Invalid command";
        }

        Process process = Runtime.getRuntime().exec(command);

        return Map.of("result", "Command executed: " + command);
    }
}
```

